-- Follow-up to 06: IP intel for the Dict 63 Linux fires (20 Nov) and the history of their one matched signature
-- (cd17e5f3fc = left 10 of MD5(DI_MATCHED_SIGNATURE_AT_SESSION_CREATED)) on Figma K2. Run 2026-11-25, Snowflake (database_id 14). No sampling.
-- A first combined version (session-list join into vw_events 09:00-14:00 + 8-day history) TIMED OUT; it was split into (a) and (b).

-- (a) Signature history at Dict 63, Linux, 13-21 Nov (28 s).
WITH h AS (SELECT session_ts ts, user_ip_at_session_created ip, latest_risk_band rb, sessions_verified ver, was_challenged chl FROM ARK_PROD.STARFLEET.PROD_INT_SESSION_SUMMARY WHERE public_key='A207F8A1-ED09-4325-ACE6-C8E26A458FBA' AND session_last_timestamp>='2026-11-13' AND session_last_timestamp<'2026-11-21 06:00' AND session_ts>='2026-11-13' AND session_ts<'2026-11-21' AND os_at_session_created IN ('GNU/Linux','Ubuntu') AND di_dictionary_num_matched_at_session_created=63 AND LEFT(MD5(di_matched_signature_at_session_created),10)='cd17e5f3fc') SELECT 'HIST|'||TO_CHAR(ts::DATE)||'|n='||COUNT(*)||'|ips='||COUNT(DISTINCT ip)||'|in_185.197.91='||COUNT_IF(ip LIKE '185.197.91.%')||'|high='||COUNT_IF(rb='High')||'|ver='||COUNT_IF(ver>0)||'|chl='||COUNT_IF(chl>0)||'|hours='||LISTAGG(DISTINCT HOUR(ts),',') WITHIN GROUP (ORDER BY HOUR(ts)) x FROM h GROUP BY ts::DATE ORDER BY 1;
-- Result: only one day: 2026-11-20 | n=37 | 4 IPs | 37 in 185.197.91.x | High 0 | verified 31 | challenged 36 | hours 9, 10, 13 UTC.
--   The signature does not appear at Dict 63 on this key 13-19 Nov (so none of its windows is in the base period).

-- (b) IP intel for all session_setup events on this key from 185.197.91.x, 20 Nov 09:40-13:40 (4.7 s). (All OS, not only the fires.)
WITH e AS (SELECT session, isp, organization org, connection_type ct, is_hosting_provider hp, is_vpn vp, vpn_proxy_description vpd, vpn_proxy_type vpt, asn, ip_intel__dx_user_ip__country cc FROM ARK_PROD.events.vw_events WHERE public_key='A207F8A1-ED09-4325-ACE6-C8E26A458FBA' AND location='session_setup' AND timestamp>='2026-11-20 09:40' AND timestamp<'2026-11-20 13:40' AND user_ip LIKE '185.197.91.%') SELECT 'INTEL|'||COALESCE(isp,'-')||'|'||COALESCE(org,'-')||'|'||COALESCE(ct,'-')||'|hosting='||COALESCE(hp::STRING,'-')||'|vpn='||COALESCE(vp::STRING,'-')||'|vpd='||COALESCE(NULLIF(vpd,''),'(empty)')||'|vpt='||COALESCE(NULLIF(vpt,''),'(empty)')||'|asn='||COALESCE(asn::STRING,'-')||'|'||COALESCE(cc,'-')||'|n='||COUNT(*)||'|sess='||COUNT(DISTINCT session) x FROM e GROUP BY isp,org,ct,hp,vp,vpd,vpt,asn,cc;
-- Result: ISP 'junta de andalucia', organization 'junta de andalucia' (39 sessions) or 'curves' (16), connection_type 'nat',
--   is_hosting_provider 0, is_vpn 0, vpn_proxy_description and vpn_proxy_type empty, ASN 34285, country ES. 55 sessions in the window.
